// Binary Heap Implementation in JavaScript (Min Heap)
class BinaryHeap {
 constructor(capacity) {
 this.capacity = capacity; // Maximum elements allowed
 this.size = 0; // Current number of elements
 this.arr = new Array(capacity); // Array to store heap elements
 }

 // Get parent index of a node at index i
 parent(i) {
 return Math.floor((i - 1) / 2);
 }

 // Get left child index of a node at index i
 left(i) {
 return 2 * i + 1;
 }

 // Get right child index of a node at index i
 right(i) {
 return 2 * i + 2;
 }

 // Swap two elements in the heap
 swap(x, y) {
 let temp = this.arr[x];
 this.arr[x] = this.arr[y];
 this.arr[y] = temp;
 }

 // Insert a new key into the heap
 insert(x) {
 if (this.size === this.capacity) {
 console.log("Binary Heap Overflow");
 return;
 }

 // Insert the new element at the end
 this.arr[this.size] = x;
 let k = this.size;
 this.size++;

 // Fix the min-heap property by bubbling up
 while (k !== 0 && this.arr[this.parent(k)] > this.arr[k]) {
 this.swap(this.parent(k), k);
 k = this.parent(k);
 }
 }

 // Heapify at index ind (fix heap property downwards)
 heapify(ind) {
 let ri = this.right(ind); // right child
 let li = this.left(ind); // left child
 let smallest = ind; // assume current node is smallest

 // If left child is smaller
 if (li < this.size && this.arr[li] < this.arr[smallest]) {
 smallest = li;
 }

 // If right child is smaller
 if (ri < this.size && this.arr[ri] < this.arr[smallest]) {
 smallest = ri;
 }

 // If smallest is not the parent, swap and recurse
 if (smallest !== ind) {
 this.swap(ind, smallest);
 this.heapify(smallest);
 }
 }

 // Get the minimum element (root)
 getMin() {
 return this.size > 0 ? this.arr[0] : null;
 }

 // Extract the minimum element
 extractMin() {
 if (this.size <= 0) return Number.MAX_SAFE_INTEGER;

 if (this.size === 1) {
 this.size--;
 return this.arr[0];
 }

 // Store minimum and move last element to root
 let mini = this.arr[0];
 this.arr[0] = this.arr[this.size - 1];
 this.size--;

 // Fix the heap property
 this.heapify(0);

 return mini;
 }

 // Decrease key at index i to new value val
 decreaseKey(i, val) {
 this.arr[i] = val;

 // Fix min-heap property upwards
 while (i !== 0 && this.arr[this.parent(i)] > this.arr[i]) {
 this.swap(i, this.parent(i));
 i = this.parent(i);
 }
 }

 // Delete element at index i
 delete(i) {
 this.decreaseKey(i, Number.MIN_SAFE_INTEGER);
 this.extractMin();
 }

 // Print heap elements
 print() {
 let output = "";
 for (let i = 0; i < this.size; i++) {
 output += this.arr[i] + " ";
 }
 console.log(output.trim());
 }
}

// Example usage
function main() {
 let h = new BinaryHeap(20);
 h.insert(4);
 h.insert(1);
 h.insert(2);
 h.insert(6);
 h.insert(7);
 h.insert(3);
 h.insert(8);
 h.insert(5);

 console.log("Min value is " + h.getMin()); // 1
 h.insert(-1);
 console.log("Min value is " + h.getMin()); // -1
 h.decreaseKey(3, -2);
 console.log("Min value is " + h.getMin()); // -2
 h.extractMin();
 console.log("Min value is " + h.getMin()); // -1
 h.delete(0);
 console.log("Min value is " + h.getMin()); // 2
}

main();

